// Forward declaration
typedef struct ImageFrameGenerator ImageFrameGenerator;

typedef struct ImageDecoderFactory {
  ImageFrameGenerator* (*CreateInstance)(void);
} ImageDecoderFactory;

typedef enum {
  DECODE_STATUS_IDLE,
  DECODE_STATUS_DECODING,
  DECODE_STATUS_FAILED,
  DECODE_STATUS_COMPLETE
} DecodeStatus;

typedef struct ImageDecoder {
  void* private_data; // Placeholder for internal decoder data
} ImageDecoder;

typedef struct ClientMutex {
  pthread_mutex_t mutex;
} ClientMutex;

typedef struct ClientMutexMap {
  ClientMutex* mutexes;
  size_t size;
} ClientMutexMap;

typedef struct ImageFrameGenerator {
  // In C, classes are not directly supported, hence this struct-based
  // representation of the class. Assuming ThreadSafeRefCounted provides
  // reference counting and thread safety.
  uint32_t ref_count;
  pthread_mutex_t ref_count_lock;

  int32_t full_width;
  int32_t full_height;

  DecodeStatus decode_status;

  uint8_t has_alpha;

  ClientMutexMap client_mutex_map;

  ImageDecoder* decoder;

  ImageDecoderFactory* decoder_factory;
} ImageFrameGenerator;

ImageFrameGenerator* ImageFrameGeneratorCreate() {
  ImageFrameGenerator* generator = (ImageFrameGenerator*)malloc(sizeof(ImageFrameGenerator));
  if (!generator) return NULL;

  generator->ref_count = 1;
  pthread_mutex_init(&generator->ref_count_lock, NULL);

  generator->full_width = 0;
  generator->full_height = 0;

  generator->decode_status = DECODE_STATUS_IDLE;
  generator->has_alpha = 0;

  generator->client_mutex_map.mutexes = NULL;
  generator->client_mutex_map.size = 0;

  generator->decoder = NULL;
  generator->decoder_factory = NULL;

  return generator;
}

void ImageFrameGeneratorAddRef(ImageFrameGenerator* generator) {
  if (generator) {
    pthread_mutex_lock(&generator->ref_count_lock);
    generator->ref_count++;
    pthread_mutex_unlock(&generator->ref_count_lock);
  }
}

void ImageFrameGeneratorRelease(ImageFrameGenerator* generator) {
  if (generator) {
    pthread_mutex_lock(&generator->ref_count_lock);
    if (--generator->ref_count == 0) {
      pthread_mutex_destroy(&generator->ref_count_lock);
      free(generator);
    } else {
      pthread_mutex_unlock(&generator->ref_count_lock);
    }
  }
}

