int32_t ImageFrameGeneratorGetHeight(ImageFrameGenerator* generator) {
  return generator->full_height;
}

int ImageFrameGeneratorIsDecodeFailed(ImageFrameGenerator* generator) {
  return generator->decode_status == DECODE_STATUS_FAILED;
}

void ImageFrameGeneratorSetDecoder(ImageFrameGenerator* generator, ImageDecoder* decoder) {
  generator->decoder = decoder;
}

