typedef struct ImageFrameGenerator ImageFrameGenerator;
typedef struct ImageDecoder ImageDecoder;

// Forward declarations for types used in ImageFrameGenerator
typedef struct {
    int width;
    int height;
} ImageSize;

typedef enum {
    DECODE_STATUS_SUCCESS,
    DECODE_STATUS_FAILURE,
    DECODE_STATUS_IN_PROGRESS
} DecodeStatus;

typedef struct {
    ImageSize full_size;
    DecodeStatus decode_status;
    int has_alpha;
    pthread_mutex_t* mutex;
} ImageFrameGeneratorState;

// Function to create a new ImageFrameGenerator instance
ImageFrameGenerator* ImageFrameGeneratorCreate(ImageDecoder* decoder, ImageSize full_size, int color_behavior, ImageSize* supported_sizes) {
    ImageFrameGenerator* self = (ImageFrameGenerator*)malloc(sizeof(ImageFrameGenerator));
    if (!self) {
        return NULL;
    }

    self->full_size = full_size;
    self->color_behavior = color_behavior;
    self->supported_sizes = supported_sizes;
    self->decode_status = DECODE_STATUS_SUCCESS;
    self->has_alpha = 0;
    self->mutex = (pthread_mutex_t*)malloc(sizeof(pthread_mutex_t));
    pthread_mutex_init(self->mutex, NULL);
    self->decoder = decoder;

    return self;
}

// Function to check if decoding has failed
int ImageFrameGeneratorIsDecodingFailed(ImageFrameGenerator* self) {
    return self->decode_status == DECODE_STATUS_FAILURE;
}

// Function to retrieve the full size of the image
ImageSize ImageFrameGeneratorGetFullSize(ImageFrameGenerator* self) {
    return self->full_size;
}

// Function to get supported decode sizes
ImageSize* ImageFrameGeneratorGetSupportedSizes(ImageFrameGenerator* self) {
    return self->supported_sizes;
}

// Function to release the ImageFrameGenerator instance
void ImageFrameGeneratorRelease(ImageFrameGenerator* self) {
    if (self->mutex) {
        pthread_mutex_destroy(self->mutex);
        free(self->mutex);
    }
    if (self->supported_sizes) {
        free(self->supported_sizes);
    }
    free(self);
}
